WHERE NOT EXISTS (
    SELECT 1 FROM public.self_quotes AS existing
    WHERE existing.hotel_name = v.hotel_name
      AND existing.check_in = v.check_in
      AND existing.check_out = v.check_out
      AND existing.collected_at = v.collected_at
      AND existing.source = v.source
      AND existing.raw_data ->> 'dataset' = v.raw_data ->> 'dataset'
